import sys

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base(n, base):
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            print("ERROR")
            continue
        number, src_str, dst_str = parts
        try:
            src = int(src_str)
            dst = int(dst_str)
        except ValueError:
            print("ERROR")
            continue
        if not (2 <= src <= 36 and 2 <= dst <= 36):
            print("ERROR")
            continue
        sign = None
        num_str = number.lower().lstrip('-')
        if num_str.startswith('-'):
            sign = '-'
            num_str = num_str[1:]
        if not num_str:
            print("ERROR")
            continue
        try:
            value = int(num_str, src)
        except ValueError:
            print("ERROR")
            continue
        if sign is None:
            print(to_base(value, dst))
        else:
            if value == 0:
                print("0")
            else:
                print(f"-{to_base(abs(value), dst)}")


if __name__ == "__main__":
    main()
